diff --git a/claude-remote-control/Dockerfile b/claude-remote-control/Dockerfile
new file mode 100644
index 0000000..780940c
--- /dev/null
+++ b/claude-remote-control/Dockerfile
@@ -0,0 +1,47 @@
+# 247 Agent Dockerfile
+# Runs the agent server with terminal support via tmux
+
+FROM node:20-slim
+
+# Install tmux and other dependencies
+RUN apt-get update && apt-get install -y \
+    tmux \
+    git \
+    curl \
+    bash \
+    && rm -rf /var/lib/apt/lists/*
+
+# Install pnpm
+RUN npm install -g pnpm
+
+# Create app directory
+WORKDIR /app
+
+# Copy package files
+COPY package.json pnpm-lock.yaml pnpm-workspace.yaml turbo.json ./
+COPY apps/agent/package.json ./apps/agent/
+COPY packages/shared/package.json ./packages/shared/
+
+# Install dependencies
+RUN pnpm install --frozen-lockfile
+
+# Copy source code
+COPY apps/agent/ ./apps/agent/
+COPY packages/shared/ ./packages/shared/
+
+# Build
+RUN pnpm build
+
+# Create data directory for SQLite
+RUN mkdir -p /root/.247/data
+
+# Expose port
+EXPOSE 4678
+
+# Health check
+HEALTHCHECK --interval=30s --timeout=10s --start-period=5s --retries=3 \
+    CMD curl -f http://localhost:4678/health || exit 1
+
+# Start agent
+WORKDIR /app/apps/agent
+CMD ["node", "dist/index.js"]
